    albumName: toBase64(song.album?.name || ""),
    crypt: 1,
    ct: 19,
    cv: 2111,
    interval: Math.floor((song.durationMs ?? 0) / 1e3),
    lrc_t: 0,
    qrc: 1,
    qrc_t: 0,
    roma: 1,
    roma_t: 0,
